-- ── story 2-8a: the QC inspection outcome ─────────────────────────────────
-- Generated by drizzle-kit (the two CREATE TABLEs and the hold-unique index)
-- and hand-amended around the generated part: the fail-fast guard, the
-- `qc_holds` status vocabulary and release pairing widened with `inspected`,
-- the inspection-line CHECKs, RLS on both new tables and the post-migration
-- probes (drizzle-kit is blind to CHECKs and policies; `bun run db:generate`
-- afterwards reports "No schema changes").
--
-- Additive. No row is rewritten: every existing hold is `open` or `released`
-- and stays so — the widened CHECKs admit exactly the rows the old ones did,
-- plus `inspected`. A non-open hold carries `released_by` / `released_at`,
-- read as "closed by / at" (an inspected hold's inspector and time). No
-- foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- Lock cost: the two CHECK re-adds on `qc_holds` scan it once under ACCESS
-- EXCLUSIVE. The table holds one row per quarantine decision — small by
-- construction — so they are added VALID (guide §3). The new tables are empty;
-- their indexes are built on nothing.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'qc_inspections'
	) THEN
		RAISE EXCEPTION 'migration 0091: qc_inspections already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "qc_inspection_lines" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"inspection_id" uuid NOT NULL,
	"batch_id" uuid,
	"outcome" text NOT NULL,
	"fail_reason" text,
	"quantity" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "qc_inspection_lines_outcome_unique" UNIQUE NULLS NOT DISTINCT("inspection_id","batch_id","outcome","fail_reason")
);
--> statement-breakpoint
CREATE TABLE "qc_inspections" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"hold_id" uuid NOT NULL,
	"note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "qc_inspections_hold_unique" ON "qc_inspections" USING btree ("tenant_id","hold_id");--> statement-breakpoint
-- ── hand-amended: the hold status vocabulary, widened ────────────────────
-- Drop and re-add (the 0023/0024 precedent). Pinned against
-- `QC_HOLD_STATUSES` (modules/inbound/qc.command.ts) by test/qc-inspection.spec.ts.
ALTER TABLE "qc_holds" DROP CONSTRAINT "qc_holds_status_check";--> statement-breakpoint
ALTER TABLE "qc_holds" ADD CONSTRAINT "qc_holds_status_check" CHECK ("status" IN ('open', 'released', 'inspected'));--> statement-breakpoint
-- A closed row (released or inspected) carries who closed it and when; an
-- open row carries neither. The DB backstop behind both commands' conditional
-- UPDATE (0014's pairing, generalised). It names no status list — the
-- vocabulary is `qc_holds_status_check`'s alone, so a fourth state widens one
-- CHECK, and an unknown status is refused by the status CHECK.
ALTER TABLE "qc_holds" DROP CONSTRAINT "qc_holds_release_pairing";--> statement-breakpoint
ALTER TABLE "qc_holds" ADD CONSTRAINT "qc_holds_release_pairing" CHECK (
	("status" = 'open') = ("released_by" IS NULL AND "released_at" IS NULL)
	-- …and the closer is whole: both columns or neither (0014 required both on
	-- a closed row; the equality above alone would admit half a closer).
	AND ("released_by" IS NULL) = ("released_at" IS NULL)
);--> statement-breakpoint
-- ── hand-amended: the inspection-line CHECKs (migration SQL only) ─────────
-- A passed row carries no reason; a failed row carries one from the
-- vocabulary. `fail_reason` is nullable, so the failed arm says IS NOT NULL
-- before IN (guide §3). Pinned against `QC_FAIL_REASONS` by
-- test/qc-inspection.spec.ts.
ALTER TABLE "qc_inspection_lines" ADD CONSTRAINT "qc_inspection_lines_outcome_check" CHECK (
	("outcome" = 'passed' AND "fail_reason" IS NULL)
	OR ("outcome" = 'failed' AND "fail_reason" IS NOT NULL
		AND "fail_reason" IN ('damaged', 'expired', 'contaminated', 'wrong-item', 'spec-failure', 'other'))
);--> statement-breakpoint
ALTER TABLE "qc_inspection_lines" ADD CONSTRAINT "qc_inspection_lines_quantity_positive" CHECK ("quantity" > 0);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0014 shape) ────────
ALTER TABLE "qc_inspections" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "qc_inspections_tenant_isolation" ON "qc_inspections"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
ALTER TABLE "qc_inspection_lines" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "qc_inspection_lines_tenant_isolation" ON "qc_inspection_lines"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0078 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (guide §3).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	b uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	h uuid := gen_random_uuid();
	i uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: an open, a released and an inspected hold; an
	-- inspection with a passed row, two failed rows of one batch under two
	-- reasons, and the untracked (null-batch) arm's passed and failed rows.
	BEGIN
		INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at")
		VALUES (gen_random_uuid(), t, w, s, b, 'open probe', 'open', u, now());
		INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","released_by","released_at")
		VALUES (gen_random_uuid(), t, w, s, b, 'released probe', 'released', u, now(), u, now()),
		       (h, t, w, s, b, 'inspected probe', 'inspected', u, now(), u, now());
		INSERT INTO "qc_inspections" ("id","tenant_id","hold_id","note") VALUES (i, t, h, NULL);
		INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
		VALUES (gen_random_uuid(), t, i, b, 'passed', NULL, 7000),
		       (gen_random_uuid(), t, i, b, 'failed', 'damaged', 2000),
		       (gen_random_uuid(), t, i, b, 'failed', 'other', 1),
		       (gen_random_uuid(), t, i, NULL, 'passed', NULL, 1000),
		       (gen_random_uuid(), t, i, NULL, 'failed', 'wrong-item', 1000);
		RAISE EXCEPTION USING ERRCODE = 'P0091', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0091: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0091' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown status', 'inspected without a closer', 'open with a closer', 'inspected with half a closer',
		'unknown outcome', 'passed with a reason', 'failed without a reason', 'unknown reason',
		'zero quantity', 'negative quantity', 'duplicate untracked row', 'second inspection of a hold'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown status' THEN 'qc_holds_status_check'
			WHEN 'inspected without a closer' THEN 'qc_holds_release_pairing'
			WHEN 'open with a closer' THEN 'qc_holds_release_pairing'
			WHEN 'inspected with half a closer' THEN 'qc_holds_release_pairing'
			WHEN 'unknown outcome' THEN 'qc_inspection_lines_outcome_check'
			WHEN 'passed with a reason' THEN 'qc_inspection_lines_outcome_check'
			WHEN 'failed without a reason' THEN 'qc_inspection_lines_outcome_check'
			WHEN 'unknown reason' THEN 'qc_inspection_lines_outcome_check'
			WHEN 'zero quantity' THEN 'qc_inspection_lines_quantity_positive'
			WHEN 'negative quantity' THEN 'qc_inspection_lines_quantity_positive'
			WHEN 'duplicate untracked row' THEN 'qc_inspection_lines_outcome_unique'
			ELSE 'qc_inspections_hold_unique'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown status' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","released_by","released_at")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', 'rejected', u, now(), u, now());
				WHEN 'inspected without a closer' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', 'inspected', u, now());
				WHEN 'open with a closer' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","released_by","released_at")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', 'open', u, now(), u, now());
				WHEN 'inspected with half a closer' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","released_by")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', 'inspected', u, now(), u);
				WHEN 'unknown outcome' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, b, 'rework', NULL, 1000);
				WHEN 'passed with a reason' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, b, 'passed', 'damaged', 1000);
				WHEN 'failed without a reason' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, b, 'failed', NULL, 1000);
				WHEN 'unknown reason' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, b, 'failed', 'smelly', 1000);
				WHEN 'zero quantity' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, b, 'passed', NULL, 0);
				WHEN 'negative quantity' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, b, 'failed', 'damaged', -1000);
				WHEN 'duplicate untracked row' THEN
					INSERT INTO "qc_inspection_lines" ("id","tenant_id","inspection_id","batch_id","outcome","fail_reason","quantity")
					VALUES (gen_random_uuid(), t, i, NULL, 'passed', NULL, 1000),
					       (gen_random_uuid(), t, i, NULL, 'passed', NULL, 2000);
				WHEN 'second inspection of a hold' THEN
					INSERT INTO "qc_inspections" ("id","tenant_id","hold_id") VALUES (gen_random_uuid(), t, h), (gen_random_uuid(), t, h);
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0091: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "qc_holds" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "qc_inspections" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "qc_inspection_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0091: a probe row survived.';
	END IF;
END $$;
